SELECT ROUND(
    AVG(amount_minor) / (
        SELECT CAST(value AS REAL)
        FROM shop_meta
        WHERE key = 'minor_units_per_dollar'
    ),
    2
) AS average_refund_dollars
FROM refunds;

SELECT MAX(DATE(delivered_at)) AS most_recent_delivery_date
FROM orders
WHERE status = 'delivered_complete';

SELECT name, country
FROM customers
WHERE RTRIM(name) LIKE '% Walsh' OR RTRIM(name) = 'Walsh';

SELECT name
FROM products
WHERE price_minor = (SELECT MIN(price_minor) FROM products);

SELECT country, COUNT(*) AS customer_count
FROM customers
GROUP BY country;

SELECT ROUND(
    100.0 * AVG(CASE WHEN EXISTS (
        SELECT 1
        FROM refunds AS r
        WHERE r.order_id = o.id
    ) THEN 1 ELSE 0 END),
    2
) AS refunded_percentage
FROM orders AS o
WHERE o.status = 'delivered_complete';

SELECT COALESCE(SUM(
           o.shipping_minor + COALESCE((
               SELECT SUM(oi.quantity * oi.unit_price_minor)
               FROM order_items AS oi
               WHERE oi.order_id = o.id
           ), 0)
       ), 0) / (
           SELECT CAST(value AS REAL)
           FROM shop_meta
           WHERE key = 'minor_units_per_dollar'
       ) AS total_charge_dollars
FROM orders AS o
WHERE o.status = 'pending_payment';

